-- Metadata only. Excludes legacy fields/indexes, which retain their separate strict gate.
SELECT md5(jsonb_build_object(
 'columns',(SELECT jsonb_agg(jsonb_build_array(c.relname,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) ORDER BY c.relname,a.attname) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname='public' AND c.relname IN ('SteamfootStoreNotice','CourseStoreNotice','DigitalManagerNotice') AND a.attname IN ('publishedAt','readAt','readById','readByName') AND NOT a.attisdropped),
 'indexes',(SELECT jsonb_agg(pg_get_indexdef(i.indexrelid) ORDER BY c.relname) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('SteamfootStoreNotice_storeId_publishedAt_id_idx','CourseStoreNotice_storeId_publishedAt_id_idx','DigitalManagerNotice_storeId_publishedAt_id_idx','SteamfootStoreNotice_unread_published_idx','CourseStoreNotice_unread_published_idx','DigitalManagerNotice_unread_published_idx','SteamfootStoreNotice_retention_idx','CourseStoreNotice_retention_idx','DigitalManagerNotice_retention_idx','DigitalManagerNotice_display_order_idx','CourseStoreNotice_beauty_published_idx') AND i.indisvalid AND i.indisready),
 'functions',(SELECT jsonb_agg(jsonb_build_array(p.proname,p.prosrc,p.prosecdef,p.proconfig,pg_get_function_result(p.oid)) ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('publish_store_notice','publish_digital_notice') AND p.pronargs=0),
 'triggers',(SELECT jsonb_agg(pg_get_triggerdef(t.oid) ORDER BY t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal AND t.tgenabled='O' AND t.tgname IN ('steam_notice_publish','course_notice_publish','digital_notice_publish'))
)::text) AS fingerprint;
